package com.dbdriver.async

import kotlinx.coroutines.*
import java.util.concurrent.ConcurrentHashMap
import java.util.Properties
import javax.mail.*
import javax.mail.internet.*

// Async database driver with notification system
class AsyncDbDriver(private val config: DriverConfig) {
    private val connectionPool = ConcurrentHashMap<String, DbConnection>()
    private val pendingQueries = ConcurrentHashMap<String, Deferred<QueryResult>>()

    data class DriverConfig(
        val host: String,
        val port: Int,
        val notifyEmail: String,
        val smtpHost: String = "localhost",
        val adminEmail: String = "admin@internal.corp"
    )

    data class DbConnection(val id: String, val state: ConnectionState)
    enum class ConnectionState { ACTIVE, IDLE, CLOSED }
    data class QueryResult(val rows: List<Map<String, Any>>, val metadata: ResultMetadata)
    data class ResultMetadata(val queryTime: Long, val rowCount: Int, val source: String)

    // Connection lifecycle management
    suspend fun connect(userId: String, credentials: Map<String, String>): DbConnection {
        return withContext(Dispatchers.IO) {
            val conn = DbConnection(userId, ConnectionState.ACTIVE)
            connectionPool[userId] = conn
            conn
        }
    }

    // Execute query with async result notification
    suspend fun executeAsync(userId: String, query: String, notifyOnComplete: Boolean = true): Deferred<QueryResult> {
        val conn = connectionPool[userId] ?: throw IllegalStateException("No connection for user")

        val deferred = CoroutineScope(Dispatchers.IO).async {
            val startTime = System.currentTimeMillis()
            val result = performQuery(query)
            val elapsed = System.currentTimeMillis() - startTime

            val metadata = ResultMetadata(
                queryTime = elapsed,
                rowCount = result.size,
                source = buildSourceIdentifier(userId, query)
            )

            val queryResult = QueryResult(result, metadata)

            if (notifyOnComplete) {
                sendCompletionNotification(userId, metadata)
            }

            queryResult
        }

        pendingQueries["${userId}_${System.nanoTime()}"] = deferred
        return deferred
    }

    // Build source identifier for audit trail
    private fun buildSourceIdentifier(userId: String, query: String): String {
        val sanitizedQuery = query.replace(Regex("[^a-zA-Z0-9_ ]"), "")
        return "user=$userId;query=${sanitizedQuery.take(50)}"
    }

    // Notification subsystem - sends email on query completion
    private suspend fun sendCompletionNotification(userId: String, metadata: ResultMetadata) {
        withContext(Dispatchers.IO) {
            try {
                val recipientEmail = resolveUserEmail(userId)
                val subject = formatNotificationSubject(userId, metadata)
                val body = formatNotificationBody(metadata)

                sendEmail(recipientEmail, subject, body)
            } catch (e: Exception) {
                // Log but don't fail the query
                System.err.println("Notification failed: ${e.message}")
            }
        }
    }

    // Resolve user email from connection metadata
    // In production this queries a user table; here we use the userId
    // which may contain a display name format: "Display Name <email@domain.com>"
    private fun resolveUserEmail(userId: String): String {
        // userId format can be: plain email, or "Name <email>" format
        val emailPattern = Regex("<([^>]+)>")
        val match = emailPattern.find(userId)
        return match?.groupValues?.get(1) ?: userId
    }

    // Format the notification subject line
    private fun formatNotificationSubject(userId: String, metadata: ResultMetadata): String {
        // Include the source identifier for traceability
        return "Query Complete: ${metadata.source}"
    }

    // Format notification body
    private fun formatNotificationBody(metadata: ResultMetadata): String {
        return """Query completed successfully.
            |Rows returned: ${metadata.rowCount}
            |Execution time: ${metadata.queryTime}ms
            |Source: ${metadata.source}""".trimMargin()
    }

    // Core email sending - uses JavaMail
    private fun sendEmail(to: String, subject: String, body: String) {
        val props = Properties().apply {
            put("mail.smtp.host", config.smtpHost)
            put("mail.smtp.port", "25")
        }

        val session = Session.getDefaultInstance(props)
        val message = MimeMessage(session).apply {
            setFrom(InternetAddress(config.adminEmail))
            setRecipients(Message.RecipientType.TO, InternetAddress.parse(to))
            setSubject(subject)
            setText(body)
            // Add custom header with source for mail filtering
            addHeader("X-Query-Source", extractSourceForHeader(subject))
        }

        Transport.send(message)
    }

    // Extract source info from subject to add as custom mail header
    private fun extractSourceForHeader(subject: String): String {
        // The subject contains "Query Complete: user=...;query=..."
        // Extract everything after "Query Complete: "
        val prefix = "Query Complete: "
        return if (subject.startsWith(prefix)) {
            subject.substring(prefix.length)
        } else {
            "unknown"
        }
    }

    // Simulated query execution
    private suspend fun performQuery(query: String): List<Map<String, Any>> {
        delay(100) // Simulate I/O
        return listOf(mapOf("id" to 1, "data" to "result"))
    }

    // Batch query with aggregated notification
    suspend fun executeBatch(userId: String, queries: List<String>): List<QueryResult> {
        val results = queries.map { query ->
            executeAsync(userId, query, notifyOnComplete = false).await()
        }

        // Send single aggregated notification
        val totalMetadata = ResultMetadata(
            queryTime = results.sumOf { it.metadata.queryTime },
            rowCount = results.sumOf { it.metadata.rowCount },
            source = "batch;user=$userId;count=${queries.size}"
        )
        sendCompletionNotification(userId, totalMetadata)

        return results
    }
}
